<script setup lang="ts">import{Head,router,useForm}from'@inertiajs/vue3';import{ref}from'vue';import AppLayout from'../../../layouts/AppLayout.vue';interface B{id:number;ip_address:string;reason:string;expires_at?:string|null;is_active:boolean;blocker?:{name:string}|null}interface L{id:number;status:string;reason?:string|null;ip_address?:string|null;created_at:string;user?:{name:string}|null}interface E{id:number;exception_class:string;request_method?:string|null;request_path?:string|null;occurrences:number;last_seen_at:string;resolved_at?:string|null;resolver?:{name:string}|null}interface A{id:number;event_type:string;target_type?:string|null;target_id?:string|null;actor_name?:string|null;created_at:string}defineProps<{blocked_ips:B[];login_logs:L[];errors:E[];audit_events:A[];can_manage:boolean}>();const tab=ref('ips'),show=ref(false);const form=useForm({ip_address:'',reason:'',expires_at:''});const block=()=>form.post('/pengaturan/keamanan/ip',{onSuccess:()=>{form.reset();show.value=false}});const dt=(v:string)=>new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));</script>
<template><AppLayout title="Keamanan"><Head title="Operasional Keamanan"/><main class="view space-y-6 security-page"><section class="hero-card security-hero"><div><p class="eyebrow">Security operations</p><h1>Keamanan & audit operasional</h1><p>Pantau blokir jaringan, percobaan login, dan error aplikasi tanpa menampilkan data rahasia.</p></div><button v-if="can_manage" class="primary-button" @click="show=true">Blokir IP</button></section><section class="panel"><div class="tabs"><button :class="{active:tab==='ips'}" @click="tab='ips'">IP terblokir</button><button :class="{active:tab==='login'}" @click="tab='login'">Log login</button><button :class="{active:tab==='errors'}" @click="tab='errors'">Log error</button><button v-if="can_manage" :class="{active:tab==='audit'}" @click="tab='audit'">Audit aktivitas</button></div><div class="table-scroll"><table v-if="tab==='ips'"><thead><tr><th>Alamat IP</th><th>Alasan</th><th>Kedaluwarsa</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="x in blocked_ips" :key="x.id"><td><code>{{x.ip_address}}</code></td><td>{{x.reason}}</td><td>{{x.expires_at?dt(x.expires_at):'Permanen'}}</td><td><span :class="['badge',x.is_active?'danger':'muted']">{{x.is_active?'Aktif':'Nonaktif'}}</span></td><td><button v-if="can_manage&&x.is_active" class="text-button" @click="router.delete(`/pengaturan/keamanan/ip/${x.id}`)">Buka blokir</button></td></tr></tbody></table><table v-else-if="tab==='login'"><thead><tr><th>Waktu</th><th>Pengguna</th><th>IP</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr v-for="x in login_logs" :key="x.id"><td>{{dt(x.created_at)}}</td><td>{{x.user?.name||'Tidak dikenal'}}</td><td><code>{{x.ip_address||'—'}}</code></td><td><span :class="['badge',x.status==='success'?'success':'danger']">{{x.status}}</span></td><td>{{x.reason||'Login berhasil'}}</td></tr></tbody></table><table v-else-if="tab==='errors'"><thead><tr><th>Terakhir</th><th>Exception</th><th>Endpoint</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><tr v-for="x in errors" :key="x.id"><td>{{dt(x.last_seen_at)}}</td><td><code>{{x.exception_class.split('\\').pop()}}</code></td><td>{{x.request_method}} /{{x.request_path}}</td><td>{{x.occurrences}}</td><td><button v-if="can_manage&&!x.resolved_at" class="text-button" @click="router.post(`/pengaturan/keamanan/error/${x.id}/selesai`)">Tandai selesai</button><span v-else class="badge success">Selesai</span></td></tr></tbody></table><table v-else><thead><tr><th>Waktu</th><th>Aktivitas</th><th>Pelaku</th><th>Target</th></tr></thead><tbody><tr v-for="x in audit_events" :key="x.id"><td>{{dt(x.created_at)}}</td><td><code>{{x.event_type}}</code></td><td>{{x.actor_name||'Pengguna tidak tersedia'}}</td><td>{{x.target_type||'—'}}<span v-if="x.target_id"> #{{x.target_id}}</span></td></tr><tr v-if="audit_events.length===0"><td colspan="4" class="empty-state">Belum ada aktivitas audit.</td></tr></tbody></table></div></section></main><div v-if="show" class="modal-backdrop" @click.self="show=false"><form class="modal-card" @submit.prevent="block"><h2>Blokir alamat IP</h2><label>Alamat IP<input v-model="form.ip_address" required placeholder="203.0.113.10"/></label><label>Alasan<textarea v-model="form.reason" required rows="3"/></label><label>Berlaku sampai (opsional)<input v-model="form.expires_at" type="datetime-local"/></label><p v-if="form.hasErrors" class="error">{{Object.values(form.errors)[0]}}</p><div class="actions"><button type="button" class="secondary-button" @click="show=false">Batal</button><button class="primary-button">Blokir</button></div></form></div></AppLayout></template>
<style scoped>.security-hero,.tabs,.actions{display:flex;align-items:center}.security-hero{justify-content:space-between;gap:1rem}.tabs{gap:.35rem;padding:1rem;border-bottom:1px solid #e2e8f0}.tabs button{padding:.55rem .8rem;border-radius:.6rem;color:#64748b;font-size:.8rem;font-weight:800}.tabs .active{background:#eef2ff;color:#4338ca}table{width:100%;border-collapse:collapse}th,td{padding:.75rem 1rem;border-bottom:1px solid #e2e8f0;text-align:left;font-size:.78rem}th{background:#f8fafc;color:#64748b;text-transform:uppercase}.badge{padding:.2rem .45rem;border-radius:999px;font-size:.68rem;font-weight:800}.danger{background:#fee2e2;color:#b91c1c}.success{background:#dcfce7;color:#15803d}.muted{background:#f1f5f9;color:#64748b}.text-button{color:#4f46e5;font-weight:800}.modal-backdrop{position:fixed;inset:0;z-index:80;display:grid;place-items:center;padding:1rem;background:rgb(15 23 42/.56)}.modal-card{width:min(500px,100%);display:grid;gap:1rem;padding:1.4rem;border-radius:1rem;background:#fff}.modal-card h2{font-weight:850}.modal-card label{display:grid;gap:.35rem;font-size:.8rem;font-weight:750}.modal-card input,.modal-card textarea{padding:.65rem;border:1px solid #cbd5e1;border-radius:.6rem}.actions{justify-content:flex-end;gap:.7rem}.error{color:#dc2626;font-size:.8rem}</style>
